from google.cloud import vision

def get_vision_client():
    return vision.ImageAnnotatorClient()

def normalize_payload(payload):
    return {
        "image_bytes": payload["image_bytes"],
    }

def normalize_response(response):
    return {
        "labels": [
            {"name": label.description, "confidence": label.score}
            for label in response.label_annotations
        ],
        "text": [text.description for text in response.text_annotations],
        "description": response.text_annotations[0].description if response.text_annotations else "No text found",
        "safety": {
            "adult": response.safe_search_annotation.adult,
            "spoof": response.safe_search_annotation.spoof,
            "medical": response.safe_search_annotation.medical,
            "violence": response.safe_search_annotation.violence,
            "racy": response.safe_search_annotation.racy,
        },
    }

from google.cloud import translate

def translate_text(text, target_language='en'):
    client = translate.TranslationServiceClient()
    parent = client.location_path('your-project-id', 'global')
    response = client.translate_text(
        request={
            'parent': parent,
            'contents': [text],
            'target_language_code': target_language,
        }
    )
    return response.translations[0].translated_text

import re

def check_unsafe_text(text):
    unsafe_patterns = [
        r'\b(badword1|badword2)\b',
        r'\b(badword3|badword4)\b',
    ]
    for pattern in unsafe_patterns:
        if re.search(pattern, text, re.IGNORECASE):
            return True
    return False

def summarize_visual_analysis(analysis_results):
    summary = {
        'labels': [label['name'] for label in analysis_results['labels']],
        'description': analysis_results['description'],
        'text': analysis_results['text'],
        'safety': analysis_results['safety'],
    }
    return summary
